/* The docs article paints every paragraph muted and leading-6. These rules sit
   outside a layer so the callout keeps its own ink and the icon's line box. */
[data-slot="callout"] [data-slot="callout-text"] {
  max-width: none;
  color: inherit;
  font-size: inherit;
  line-height: inherit;
}

[data-slot="callout"] [data-slot="callout-text"] a {
  color: inherit;
}

/* Soft wash, surface, and outline for Callout. Imported by Callout.tsx. */
@layer components {
  [data-slot="callout"] {
    --callout-ink: var(--foreground);
    --callout-wash: var(--gray-panel);
    --callout-line: var(--border);
  }

  [data-slot="callout"][data-color="indigo"] {
    --callout-ink: var(--indigo-ink-strong);
    --callout-wash: var(--indigo-panel);
    --callout-line: var(--indigo-line);
  }
  [data-slot="callout"][data-color="cyan"] {
    --callout-ink: var(--cyan-ink-strong);
    --callout-wash: var(--cyan-panel);
    --callout-line: var(--cyan-line);
  }
  [data-slot="callout"][data-color="orange"] {
    --callout-ink: var(--orange-ink-strong);
    --callout-wash: var(--orange-panel);
    --callout-line: var(--orange-line);
  }
  [data-slot="callout"][data-color="crimson"] {
    --callout-ink: var(--crimson-ink-strong);
    --callout-wash: var(--crimson-panel);
    --callout-line: var(--crimson-line);
  }
  [data-slot="callout"][data-color="jade"] {
    --callout-ink: var(--jade-ink-strong);
    --callout-wash: var(--jade-panel);
    --callout-line: var(--jade-line);
  }

  [data-slot="callout"][data-high-contrast="true"][data-color="gray"] {
    --callout-ink: var(--foreground);
    --callout-line: var(--foreground);
  }
  [data-slot="callout"][data-high-contrast="true"][data-color="indigo"] {
    --callout-ink: var(--indigo-ink-deep);
    --callout-line: color-mix(in oklch, var(--indigo-ink-deep) 55%, transparent);
  }
  [data-slot="callout"][data-high-contrast="true"][data-color="cyan"] {
    --callout-ink: var(--cyan-ink-deep);
    --callout-line: color-mix(in oklch, var(--cyan-ink-deep) 55%, transparent);
  }
  [data-slot="callout"][data-high-contrast="true"][data-color="orange"] {
    --callout-ink: var(--orange-ink-deep);
    --callout-line: color-mix(in oklch, var(--orange-ink-deep) 55%, transparent);
  }
  [data-slot="callout"][data-high-contrast="true"][data-color="crimson"] {
    --callout-ink: var(--crimson-ink-deep);
    --callout-line: color-mix(in oklch, var(--crimson-ink-deep) 55%, transparent);
  }
  [data-slot="callout"][data-high-contrast="true"][data-color="jade"] {
    --callout-ink: var(--jade-ink-deep);
    --callout-line: color-mix(in oklch, var(--jade-ink-deep) 55%, transparent);
  }

  [data-slot="callout"][data-variant="soft"] {
    background: var(--callout-wash);
    color: var(--callout-ink);
  }

  [data-slot="callout"][data-variant="surface"] {
    background: color-mix(in oklch, var(--callout-wash) 58%, white);
    color: var(--callout-ink);
    box-shadow: inset 0 0 0 1px var(--callout-line);
  }

  .dark [data-slot="callout"][data-variant="surface"] {
    background: color-mix(in oklch, var(--callout-wash) 72%, black);
  }

  [data-slot="callout"][data-variant="outline"] {
    background: transparent;
    color: var(--callout-ink);
    box-shadow: inset 0 0 0 1px var(--callout-line);
  }
}

